import { PencilLine, Power } from 'lucide-react';
import { formatQuantity } from '../../../utils/format.js';

const ActiveBadge = ({ isActive }) => (
  <span
      className={`inline-flex items-center rounded-full border px-2.5 py-0.5 text-[11px] font-semibold ${
            isActive
                    ? 'border-leaf-200 bg-leaf-50 text-primary-700'
                            : 'border-sand-300 bg-sand-100 text-primary-500'
                                }`}
                                  >
                                      {isActive ? 'Active' : 'Inactive'}
                                        </span>
                                        );

                                        const ItemName = ({ drug }) => (
                                          <div className="min-w-0">
                                              <p className="truncate text-sm font-semibold text-primary-900">{drug.name}</p>
                                                  <p className="truncate text-xs text-primary-500">
                                                        {drug.code}
                                                              {drug.genericName ? ` · ${drug.genericName}` : ''}
                                                                  </p>
                                                                    </div>
                                                                    );

                                                                    const Actions = ({ drug, canManage, onEdit, onToggle, busy }) => {
                                                                      if (!canManage) {
                                                                          return null;
                                                                            }

                                                                              return (
                                                                                  <div className="flex items-center justify-end gap-1">
                                                                                        <button
                                                                                                type="button"
                                                                                                        onClick={(event) => {
                                                                                                                  event.stopPropagation();
                                                                                                                            onEdit(drug);
                                                                                                                                    }}
                                                                                                                                            aria-label={`Edit ${drug.name}`}
                                                                                                                                                    className="rounded-lg p-2 text-primary-600 transition hover:bg-primary-50 hover:text-primary-800"
                                                                                                                                                          >
                                                                                                                                                                  <PencilLine className="h-4 w-4" aria-hidden="true" />
                                                                                                                                                                        </button>
                                                                                                                                                                              <button
                                                                                                                                                                                      type="button"
                                                                                                                                                                                              disabled={busy}
                                                                                                                                                                                                      onClick={(event) => {
                                                                                                                                                                                                                event.stopPropagation();
                                                                                                                                                                                                                          onToggle(drug);
                                                                                                                                                                                                                                  }}
                                                                                                                                                                                                                                          aria-label={drug.isActive ? `Deactivate ${drug.name}` : `Reactivate ${drug.name}`}
                                                                                                                                                                                                                                                  className={`rounded-lg p-2 transition disabled:opacity-40 ${
                                                                                                                                                                                                                                                            drug.isActive
                                                                                                                                                                                                                                                                        ? 'text-maroon-600 hover:bg-maroon-50'
                                                                                                                                                                                                                                                                                    : 'text-primary-600 hover:bg-leaf-50'
                                                                                                                                                                                                                                                                                            }`}
                                                                                                                                                                                                                                                                                                  >
                                                                                                                                                                                                                                                                                                          <Power className="h-4 w-4" aria-hidden="true" />
                                                                                                                                                                                                                                                                                                                </button>
                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                      };

                                                                                                                                                                                                                                                                                                                      export default function DrugTable({ drugs, loading, canManage, onEdit, onToggle, busyId }) {
                                                                                                                                                                                                                                                                                                                        if (loading) {
                                                                                                                                                                                                                                                                                                                            return (
                                                                                                                                                                                                                                                                                                                                  <div className="divide-y divide-sand-100">
                                                                                                                                                                                                                                                                                                                                          {Array.from({ length: 6 }).map((_, index) => (
                                                                                                                                                                                                                                                                                                                                                    <div key={index} className="px-4 py-4 sm:px-5">
                                                                                                                                                                                                                                                                                                                                                                <div className="h-4 w-2/3 animate-pulse rounded bg-sand-200" />
                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                  ))}
                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                return (
                                                                                                                                                                                                                                                                                                                                                                                                    <>
                                                                                                                                                                                                                                                                                                                                                                                                          <div className="hidden overflow-x-auto md:block">
                                                                                                                                                                                                                                                                                                                                                                                                                  <table className="w-full border-collapse text-sm">
                                                                                                                                                                                                                                                                                                                                                                                                                            <thead>
                                                                                                                                                                                                                                                                                                                                                                                                                                        <tr className="border-b border-sand-200 text-left text-[11px] uppercase tracking-wide text-primary-500">
                                                                                                                                                                                                                                                                                                                                                                                                                                                      <th className="px-5 py-3 font-semibold">Drug</th>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <th className="px-3 py-3 font-semibold">Strength / form</th>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <th className="px-3 py-3 font-semibold">Unit</th>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <th className="px-3 py-3 text-right font-semibold">Minimum</th>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <th className="px-3 py-3 font-semibold">Status</th>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <th className="px-3 py-3 text-right font-semibold">Actions</th>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </thead>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <tbody className="divide-y divide-sand-100">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {drugs.map((drug) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <tr key={drug.id} className="transition hover:bg-primary-50/40">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <td className="max-w-[22rem] px-5 py-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <ItemName drug={drug} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <td className="px-3 py-3 text-primary-600">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {drug.strength || '—'}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <span className="text-primary-400"> · </span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {drug.dosageForm}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <td className="whitespace-nowrap px-3 py-3 text-primary-600">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {drug.unitOfMeasure}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <td className="whitespace-nowrap px-3 py-3 text-right text-primary-700">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {formatQuantity(drug.minimumStockLevel)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <td className="px-3 py-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <ActiveBadge isActive={drug.isActive} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <td className="px-3 py-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Actions
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          drug={drug}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              canManage={canManage}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  onEdit={onEdit}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      onToggle={onToggle}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          busy={busyId === drug.id}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </tbody>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </table>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <ul className="divide-y divide-sand-100 md:hidden">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {drugs.map((drug) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <li key={drug.id} className="flex items-start gap-3 px-4 py-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="min-w-0 flex-1">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <ItemName drug={drug} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <p className="mt-1 text-xs text-primary-500">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {drug.strength ? `${drug.strength} · ` : ''}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {drug.dosageForm} · min {formatQuantity(drug.minimumStockLevel)}{' '}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {drug.unitOfMeasure}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="mt-1.5">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <ActiveBadge isActive={drug.isActive} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Actions
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              drug={drug}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            canManage={canManage}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onEdit={onEdit}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        onToggle={onToggle}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      busy={busyId === drug.id}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </li>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </ul>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }